def ua_usage(exclude_id=None):
    from core.db import get_conn
    conn = get_conn()
    cols = [r["name"] for r in conn.execute("PRAGMA table_info(social_accounts)").fetchall()]
    if "user_agent" not in cols:
        conn.close()
        return {}
    q = "SELECT label, user_agent FROM social_accounts WHERE user_agent IS NOT NULL AND user_agent != ''"
    args = []
    if exclude_id:
        q += " AND id != ?"
        args.append(exclude_id)
    rows = conn.execute(q, args).fetchall()
    conn.close()
    used = {}
    for r in rows:
        used.setdefault(r["user_agent"], []).append(r["label"])
    return used
